SELECT chart_aggregation_jobs.kind, chart_aggregation_jobs.id, chart_aggregation_jobs.instrument_id, chart_aggregation_jobs.timeframe, chart_aggregation_jobs.start, chart_aggregation_jobs."end", chart_aggregation_jobs.created_at, chart_aggregation_jobs.attempts, chart_aggregation_jobs.next_at, chart_aggregation_jobs.error, instruments.id AS id_1, instruments.label, instruments.source, instruments.symbol, instruments.basis, instruments.calendar, instruments.calendar_profile, instruments.precision, instruments.quality, instruments.last_received, instruments.error AS error_1, instruments.enabled
FROM chart_aggregation_jobs JOIN instruments ON instruments.id = chart_aggregation_jobs.instrument_id LEFT OUTER JOIN chart_aggregation_state ON chart_aggregation_state.instrument_id = chart_aggregation_jobs.instrument_id AND chart_aggregation_state.timeframe = chart_aggregation_jobs.timeframe
WHERE chart_aggregation_jobs.next_at <= 1792022400000 ORDER BY coalesce(chart_aggregation_state.last_service_seq, 0), CASE WHEN (chart_aggregation_jobs.created_at <= 1792022390000) THEN 0 WHEN (EXISTS (SELECT chart_viewport_demands.id
FROM chart_viewport_demands
WHERE chart_viewport_demands.instrument_id = chart_aggregation_jobs.instrument_id AND chart_viewport_demands.expires > 1792022400000 AND CASE WHEN (chart_viewport_demands.timeframe = 'M30') THEN 'M15' ELSE chart_viewport_demands.timeframe END = chart_aggregation_jobs.timeframe AND chart_aggregation_jobs.start < chart_viewport_demands."end" AND chart_aggregation_jobs."end" > chart_viewport_demands.start AND chart_viewport_demands.focused IS true)) THEN 100 WHEN (EXISTS (SELECT chart_viewport_demands.id
FROM chart_viewport_demands
WHERE chart_viewport_demands.instrument_id = chart_aggregation_jobs.instrument_id AND chart_viewport_demands.expires > 1792022400000 AND CASE WHEN (chart_viewport_demands.timeframe = 'M30') THEN 'M15' ELSE chart_viewport_demands.timeframe END = chart_aggregation_jobs.timeframe AND chart_aggregation_jobs.start < chart_viewport_demands."end" AND chart_aggregation_jobs."end" > chart_viewport_demands.start)) THEN 110 WHEN (EXISTS (SELECT chart_viewport_demands.id
FROM chart_viewport_demands
WHERE chart_viewport_demands.instrument_id = chart_aggregation_jobs.instrument_id AND chart_viewport_demands.expires > 1792022400000 AND chart_aggregation_jobs.start < chart_viewport_demands."end" AND chart_aggregation_jobs."end" > chart_viewport_demands.warm_start AND chart_viewport_demands.focused IS true)) THEN 130 WHEN (EXISTS (SELECT chart_viewport_demands.id
FROM chart_viewport_demands
WHERE chart_viewport_demands.instrument_id = chart_aggregation_jobs.instrument_id AND chart_viewport_demands.expires > 1792022400000 AND chart_aggregation_jobs.start < chart_viewport_demands."end" AND chart_aggregation_jobs."end" > chart_viewport_demands.warm_start)) THEN 150 WHEN (EXISTS (SELECT chart_viewport_demands.id
FROM chart_viewport_demands
WHERE chart_viewport_demands.instrument_id = chart_aggregation_jobs.instrument_id AND chart_viewport_demands.expires > 1792022400000)) THEN 170 ELSE 300 END, CASE WHEN (chart_aggregation_jobs.created_at <= 1792022390000) THEN chart_aggregation_jobs.created_at ELSE -chart_aggregation_jobs."end" END, chart_aggregation_jobs.created_at, chart_aggregation_jobs.id
 LIMIT 1 FOR UPDATE OF instruments SKIP LOCKED;
